begin;
create function pg_temp.r_id(n integer) returns uuid language sql immutable as $$select ('80000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.r_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;end$$;
create function pg_temp.r_error(statement text,state text) returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate=state then return;end if;raise;end;raise exception 'Expected %',state;end$$;
create function pg_temp.r_command(n integer default 0) returns jsonb language sql as $$select jsonb_build_object('commandId',pg_temp.r_id(n+1),'expectedVersion',0,'entry',jsonb_build_object('id',pg_temp.r_id(n+2),'registrationId',pg_temp.r_id(95),'personId',pg_temp.r_id(50),'jersey',case when n=0 then '0' else '00' end,'active',true))$$;
grant execute on function pg_temp.r_id(integer),pg_temp.r_assert(boolean,text),pg_temp.r_error(text,text),pg_temp.r_command(integer) to anon,authenticated;
delete from public.admin_access;
insert into auth.users(id) values(pg_temp.r_id(98)),(pg_temp.r_id(99));
insert into public.admin_access(user_id) values(pg_temp.r_id(98));
insert into public.championships(id,name) values(pg_temp.r_id(90),'Roster fixture');
insert into public.seasons(id,championship_id,year) values(pg_temp.r_id(91),pg_temp.r_id(90),2026);
insert into public.disputes(id,season_id,gender,category) values(pg_temp.r_id(92),pg_temp.r_id(91),'feminino','Adulto'),(pg_temp.r_id(93),pg_temp.r_id(91),'feminino','Sub-18');
insert into public.teams(id,name) values(pg_temp.r_id(94),'Team fixture');
insert into public.registrations(id,dispute_id,team_id,name) values(pg_temp.r_id(95),pg_temp.r_id(92),pg_temp.r_id(94),'Team A'),(pg_temp.r_id(96),pg_temp.r_id(92),pg_temp.r_id(94),'Team B'),(pg_temp.r_id(97),pg_temp.r_id(93),pg_temp.r_id(94),'Other dispute');
insert into public.persons(id,name) values(pg_temp.r_id(50),'Pessoa 50'),(pg_temp.r_id(51),'Pessoa 51'),(pg_temp.r_id(52),'Pessoa 52'),(pg_temp.r_id(54),'Pessoa 54');
insert into private.athletes(person_id,sex) values(pg_temp.r_id(50),'female'),(pg_temp.r_id(51),'female'),(pg_temp.r_id(52),'male'),(pg_temp.r_id(54),'female');
set local role anon;
select pg_temp.r_error('select public.list_roster(pg_temp.r_id(95))','42501');
set local role authenticated;
set local request.jwt.claim.sub='80000000-0000-4000-8000-000000000099';
select pg_temp.r_error('select public.save_roster_entry(pg_temp.r_command())','PT403');
set local request.jwt.claim.sub='80000000-0000-4000-8000-000000000098';
select pg_temp.r_error('delete from public.roster_entries','42501');
select public.save_roster_entry(pg_temp.r_command());
select public.save_roster_entry(pg_temp.r_command());
select public.save_roster_entry(jsonb_set(pg_temp.r_command(10),'{entry,personId}',to_jsonb(pg_temp.r_id(51))));
select pg_temp.r_assert(public.list_roster(pg_temp.r_id(95))->'items'->0->>'jersey'='0' and public.list_roster(pg_temp.r_id(95))->'items'->1->>'jersey'='00','0 and 00 remain distinct and ordered');
select pg_temp.r_error($q$select public.save_roster_entry(jsonb_set(pg_temp.r_command(20),'{entry,registrationId}',to_jsonb(pg_temp.r_id(96))))$q$,'PT400');
select pg_temp.r_error($q$select public.save_roster_entry(jsonb_set(jsonb_set(pg_temp.r_command(30),'{entry,personId}',to_jsonb(pg_temp.r_id(54))),'{entry,jersey}','"0"'))$q$,'PT400');
select pg_temp.r_error($q$select public.save_roster_entry(jsonb_set(pg_temp.r_command(70),'{entry,personId}',to_jsonb(pg_temp.r_id(52))))$q$,'PT400');
select public.save_roster_entry(jsonb_set(pg_temp.r_command(40),'{entry,registrationId}',to_jsonb(pg_temp.r_id(97))));
select pg_temp.r_error($q$select public.save_roster_entry(jsonb_set(jsonb_set(jsonb_set(pg_temp.r_command(),'{commandId}',to_jsonb(pg_temp.r_id(60))),'{expectedVersion}','1'),'{entry,registrationId}',to_jsonb(pg_temp.r_id(96))))$q$,'PT400');
select public.save_roster_entry(jsonb_set(jsonb_set(jsonb_set(pg_temp.r_command(),'{commandId}',to_jsonb(pg_temp.r_id(60))),'{expectedVersion}','1'),'{entry,jersey}','"7"'));
select pg_temp.r_error($q$select public.save_roster_entry(jsonb_set(pg_temp.r_command(),'{commandId}',to_jsonb(pg_temp.r_id(61))))$q$,'PT409');
select public.save_roster_entry(jsonb_set(jsonb_set(jsonb_set(jsonb_set(pg_temp.r_command(),'{commandId}',to_jsonb(pg_temp.r_id(61))),'{expectedVersion}','2'),'{entry,jersey}','"7"'),'{entry,active}','false'));
select pg_temp.r_assert((public.get_roster_entry(pg_temp.r_id(2))->>'active')::boolean=false and public.get_roster_entry(pg_temp.r_id(2))->>'endedAt' is not null,'inactive history retained');
-- New periods now require the explicit transfer writer, even after inactivation.
select pg_temp.r_error($q$select public.save_roster_entry(jsonb_set(pg_temp.r_command(20),'{entry,registrationId}',to_jsonb(pg_temp.r_id(96))))$q$,'PT400');
select public.save_roster_entry(jsonb_set(jsonb_set(pg_temp.r_command(20),'{entry,registrationId}',to_jsonb(pg_temp.r_id(96))),'{entry,personId}',to_jsonb(pg_temp.r_id(54))));
select pg_temp.r_assert(jsonb_array_length(public.list_roster(pg_temp.r_id(95))->'items')=1 and jsonb_array_length(public.list_roster(pg_temp.r_id(95),false)->'items')=2,'history separately inspectable');
select pg_temp.r_error($q$select public.save_roster_entry(jsonb_set(jsonb_set(pg_temp.r_command(),'{commandId}',to_jsonb(pg_temp.r_id(62))),'{expectedVersion}','3'))$q$,'PT400');
select pg_temp.r_assert(not ((public.get_roster_entry(pg_temp.r_id(12))->'person') ? 'athlete'),'roster projection excludes private athlete details');
reset role;
-- Global edits must not invalidate an existing active context.
select pg_temp.r_error($q$update private.athletes set sex='male' where person_id=pg_temp.r_id(50)$q$,'PT400');
select pg_temp.r_error($q$update public.disputes set gender='masculino' where id=pg_temp.r_id(92)$q$,'PT400');
select pg_temp.r_assert((select sex='female' from private.athletes where person_id=pg_temp.r_id(50)),'global sex mismatch rolled back');
update public.roster_entries set ended_at=clock_timestamp() where person_id=pg_temp.r_id(50) and ended_at is null;
update private.athletes set sex='male' where person_id=pg_temp.r_id(50);
select pg_temp.r_assert((select sex='male' from private.athletes where person_id=pg_temp.r_id(50)),'inactive history does not freeze current private sex');
update public.admin_access set enabled=false;
set local role authenticated;
select pg_temp.r_assert(public.get_roster_entry(pg_temp.r_id(2)) is null,'revoked reads');
select pg_temp.r_error('select public.save_roster_entry(pg_temp.r_command())','PT403');
reset role;
rollback;
